const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const thailand = ee.FeatureCollection('USDOS/LSIB_SIMPLE/2017')
    .filter(ee.Filter.eq('country_na', 'Thailand'))
    .geometry();

  // 2. Data Acquisition for August 2008
  const aug2008 = ee.ImageCollection('MODIS/006/MCD64A1')
    .filterDate('2008-08-01', '2008-08-32')
    .filterBounds(thailand);

  const aug2008Size = await aug2008.size().getInfo();
  console.log(`August 2008 Images: ${aug2008Size}`);

  // 3. Data Acquisition for February 2008
  const feb2008 = ee.ImageCollection('MODIS/006/MCD64A1')
    .filterDate('2008-02-01', '2008-03-01')
    .filterBounds(thailand);

  const feb2008Size = await feb2008.size().getInfo();
  console.log(`February 2008 Images: ${feb2008Size}`);

  if (aug2008Size === 0 || feb2008Size === 0) {
    console.log('No images found for one or both periods.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 4. Process burned area for August 2008
  // Day of year for August: 213-243 (Aug 1 = day 214 in leap year 2008)
  const augImage = aug2008.select('BurnDate').mosaic();
  const augBurned = augImage.gte(214).and(augImage.lte(243));

  const augStats = await augBurned.reduceRegion({
    reducer: ee.Reducer.sum().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: thailand,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const augBurnedPixels = augStats.BurnDate_sum || 0;
  const augTotalPixels = augStats.BurnDate_count || 0;

  console.log(`August 2008 - Burned pixels: ${augBurnedPixels}, Total pixels: ${augTotalPixels}`);

  // 5. Process burned area for February 2008
  // Day of year for February: 32-60 (Feb 1 = day 32, Feb 29 = day 60 in leap year)
  const febImage = feb2008.select('BurnDate').mosaic();
  const febBurned = febImage.gte(32).and(febImage.lte(60));

  const febStats = await febBurned.reduceRegion({
    reducer: ee.Reducer.sum().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: thailand,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const febBurnedPixels = febStats.BurnDate_sum || 0;
  const febTotalPixels = febStats.BurnDate_count || 0;

  console.log(`February 2008 - Burned pixels: ${febBurnedPixels}, Total pixels: ${febTotalPixels}`);

  // 6. Validation & Final Answer
  if (augTotalPixels === 0 || febTotalPixels === 0) {
    console.log('No valid pixels after processing.');
    console.log('<answer>C2</answer>');
    return;
  }

  if (augBurnedPixels === null || febBurnedPixels === null || 
      isNaN(augBurnedPixels) || isNaN(febBurnedPixels)) {
    console.log('Calculation returned invalid values.');
    console.log('<answer>C3</answer>');
    return;
  }

  console.log(`Comparison: August ${augBurnedPixels} vs February ${febBurnedPixels}`);

  if (augBurnedPixels > febBurnedPixels) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
